class Account {
  #balance = 0;

  constructor(owner, opening = 0) {
    if (!Number.isFinite(opening) || opening < 0) throw new RangeError("opening must be non-negative");
    this.owner = owner;
    this.#balance = opening;
  }

  get balance() { return this.#balance; }
  deposit(amount) {
    if (!Number.isFinite(amount) || amount <= 0) throw new RangeError("invalid amount");
    this.#balance += amount;
    return this;
  }

  static createStarter(owner) { return new this(owner, 0); }
}

class SavingsAccount extends Account {
  constructor(owner, opening, rate) {
    super(owner, opening); // must run before using this
    this.rate = rate;
  }
  addMonthlyInterest() { this.deposit(this.balance * this.rate); }
}

const account = new SavingsAccount("Mina", 100, 0.02);
account.addMonthlyInterest();
